package com.example.platform.delivery;

import java.time.Duration;

/**
 * Exponential backoff for outbound webhook delivery.
 *
 * <p>The attempt counter is held on the {@link DeliveryRecord}, not on the
 * circuit breaker. Holding it on the breaker was the cause of OPS-42: a
 * half-open transition reset the counter and delivery gave up after 3
 * attempts instead of 8.
 */
public final class RetryPolicy {

    private static final int MAX_ATTEMPTS = 8;
    private static final Duration BASE_DELAY = Duration.ofSeconds(2);
    private static final double MULTIPLIER = 2.0;
    private static final Duration MAX_DELAY = Duration.ofMinutes(15);

    private RetryPolicy() {
    }

    public static boolean shouldRetry(DeliveryRecord record) {
        return record.attemptCount() < MAX_ATTEMPTS && record.isRetryable();
    }

    public static Duration nextDelay(int attempt) {
        if (attempt < 1) {
            throw new IllegalArgumentException("attempt must be >= 1");
        }
        long millis = (long) (BASE_DELAY.toMillis() * Math.pow(MULTIPLIER, attempt - 1));
        return Duration.ofMillis(Math.min(millis, MAX_DELAY.toMillis()));
    }

    public static int maxAttempts() {
        return MAX_ATTEMPTS;
    }
}
